import * as api from './test-data.mjs';
import {FieldValidation} from './field-view-model.mjs';
import {$,esc,table} from './test-view.mjs';
import {fmt,pct,utc} from './test-model.mjs';
const statusLabels={'diagnostic-complete':'Holdout diagnostic complete','insufficient-compatible-data':'Insufficient compatible data','insufficient-training':'Insufficient training evidence','insufficient-holdout':'Insufficient holdout evidence'};
const number=value=>Number.isFinite(value)?fmt(value,2):'—';
const signed=value=>Number.isFinite(value)?`${value>0?'+':''}${number(value)}`:'—';
const show=(id,yes)=>{$(id).hidden=!yes;};
const setValue=(id,value)=>{if(document.activeElement!==$(id))$(id).value=value;};
const cutoff=value=>Number.isFinite(value)?new Date(value).toISOString():'';

export function bindFieldValidation({getWorkspace,download}){
 $('field-validation').innerHTML=`<div class="field-heading"><div><p class="overline">MEASUREMENT / MODEL / HOLDOUT</p><h2 id="field-heading" tabindex="-1">Field validation</h2><p id="field-scope" class="note"></p></div></div>
 <p class="field-intro">Compare declared operator carrier-power measurements with a frozen source-cell simulation. Fit a diagnostic offset on earlier sites and check it on later, separate sites.</p>
 <p class="model-note">RSRP and RSSI use different measurement definitions. These models predict desired-carrier mean power; no conversion is inferred. Source declarations and instrumentation remain unverified.</p>
 <p id="field-error" class="error" role="alert" hidden></p>
 <section class="panel field-panel"><h3>1. Choose the evidence</h3><div class="fields two"><label>Operator capture<select id="field-capture"></select></label><label>Frozen source-cell run<select id="field-prediction"></select></label></div>
 <p id="field-empty" class="note"></p><p id="field-source-state" class="note" role="status"></p>
 <div class="field-descriptor"><label>Measurement descriptor JSON<input id="field-file" type="file" accept=".json,application/json"></label><button id="field-template" type="button">Download measurement template</button><button id="field-check" type="button">Check compatibility</button></div>
 <p id="field-file-state" class="helper">Use the template to declare instrument calibration, reference plane, averaging, actual configuration and observed-cell mappings.</p>
 <p id="field-compatibility" class="field-status" role="status"></p><div id="field-issues"></div>
 <details><summary>Measurement definitions and evidence</summary><p class="note">The capture must contain measured_rx_dbm, explicit measurement_status, actual GPS, band, channel and an observed cell ID. A declared operator configuration record must match every frozen transmit, antenna, geometry and receiver assumption during the capture. The descriptor pins the capture, prediction, equipment and route hashes. The template leaves attestation fields blank.</p><p class="note">LTE RSRP averages power on cell-specific reference-signal resource elements; NR SS-RSRP uses synchronization-signal resource elements. RSSI includes other signals and noise. A desired-carrier total-power model cannot supply either definition.</p><p class="note"><a href="https://www.etsi.org/deliver/etsi_ts/136200_136299/136214/18.01.00_60/ts_136214v180100p.pdf" target="_blank" rel="noopener">TS 36.214 v18.1.0</a> · <a href="https://www.etsi.org/deliver/etsi_ts/138200_138299/138215/18.02.00_60/ts_138215v180200p.pdf" target="_blank" rel="noopener">TS 38.215 v18.2.0</a></p><div id="field-source-facts"></div></details></section>
 <section class="panel field-panel"><h3>2. Reserve an independent holdout</h3><p class="note">Training uses earlier readings from the other physical sites. Holdout uses later readings from the checked sites. Wrong site/time combinations and the time gap are quarantined.</p>
 <div class="fields two"><label>Split cutoff (UTC ISO 8601)<input id="field-cutoff" type="text" placeholder="2026-11-02T12:03:00.000Z" spellcheck="false"></label><label>Time gap on each side (s)<input id="field-time-gap" type="number" min="0" max="86400" step="1" value="60"></label></div>
 <fieldset class="field-sites"><legend>Sites reserved for the later holdout</legend><p id="field-site-count" class="helper"></p><label>Find holdout sites<input id="field-site-search" type="search" placeholder="Site ID or name"></label><div id="field-sites"></div><button id="field-more-sites" type="button" hidden>Show more sites</button></fieldset>
 <details><summary>Route matching and quality limits</summary><div class="fields two"><label>Capture direction<select id="field-direction"><option value="forward">Forward</option><option value="reverse">Reverse</option></select></label><label>Route tolerance (m)<input id="field-tolerance" type="number" min="1" max="200" step="any" value="50"></label><label>Route continuity gap (s)<input id="field-route-gap" type="number" min="0.001" max="3600" step="0.001" value="10"></label><label>Minimum compatible readings (%)<input id="field-minimum" type="number" min="1" max="100" step="any" value="90"></label></div></details>
 <p class="note">Equal 20 m cell/carrier/environment bins use linear-power averages. At least 30 bins and two physical sites are required in each cohort. Holdout carriers and environments absent from training receive no correction.</p><p id="field-options-state" class="helper"></p><div class="actions"><button id="field-run" class="primary" type="button">Run field study</button><button id="field-cancel" type="button" hidden>Cancel field study</button></div><p id="field-progress" role="status"></p><progress id="field-progress-bar" max="100" value="0" aria-label="Field study progress" hidden></progress></section>
 <section id="field-output" class="panel field-panel" hidden><div class="panel-head"><div><h3>3. Review the saved diagnostic</h3><p id="field-result-source" class="mono"></p></div><button id="field-export" type="button">Export field study</button></div><p id="field-stale" class="model-note" hidden>Form inputs have changed. These results retain the saved study’s original inputs. Run a new study to evaluate the edited form.</p><h4 id="field-result-status"></h4><div id="field-cards" class="field-cards"></div><div id="field-metrics"></div>
 <p class="note">Residual = measured minus model power. A positive offset raises the candidate prediction. The offset uses training bins only. Raw and adjusted holdout errors use the same supported bins.</p>
 <details><summary>Excluded readings, quarantine and limits</summary><div id="field-reasons"></div><p id="field-limits" class="note"></p></details>
 <div class="field-records"><div class="actions"><label>Saved study records<select id="field-record-kind"><option value="bins">20 m bins</option><option value="bySite">Site summaries</option><option value="byCarrier">Carrier summaries</option><option value="byEnvironment">Environment summaries</option><option value="observations">Observation screening</option></select></label><button id="field-rows-reload" type="button">Reload study rows</button></div><div id="field-records"></div><div class="pagination"><button id="field-page-prev" type="button">Previous study rows</button><span id="field-page" role="status"></span><button id="field-page-next" type="button">Next study rows</button></div></div></section>
 <details class="panel field-panel"><summary>Saved field studies</summary><button id="field-history-refresh" type="button">Refresh field studies</button><div id="field-history"></div></details>`;
 const state=new FieldValidation(api,()=>crypto.randomUUID());let active=false,timer,sourceSignature='',siteSignature='',historySignature='',resultSignature='',pageSignature='',siteFilter='',siteLimit=50,reading=0,fileLabel='',autoPageStudy='';
 function sources(){
  const signature=JSON.stringify([state.captures,state.predictions].map(list=>list.map(t=>[t.id,t.label])));
  if(signature!==sourceSignature){sourceSignature=signature;for(const [id,list,label]of [['field-capture',state.captures,'Choose an imported capture'],['field-prediction',state.predictions,'Choose a frozen run']])$(id).replaceChildren(new Option(label,''),...list.map(t=>new Option(`${t.label} / ${t.id}`,t.id)));}
  setValue('field-capture',state.captureId);setValue('field-prediction',state.predictionId);
  $('field-empty').textContent=!state.captures.length?'Import an operator capture to start. Synthetic demos and simulated runs are excluded from measurement evidence.':!state.predictions.length?'Create a source-cell virtual drive with the matching equipment and configuration.':'Choose inputs from the same Project and Task. The frozen run supplies the route and model; current planning edits are not substituted.';
  $('field-source-state').textContent=state.busy==='inputs'?'Loading source identities…':state.inputs?`Capture ${utc(state.inputs.capture.start)} to ${utc(state.inputs.capture.end)} · ${state.inputs.sites.length} frozen physical sites.`:'';
  const issues=state.compatibility?.issues||[];$('field-compatibility').textContent=state.busy==='check'?'Checking declared measurement compatibility…':state.compatibility?.ready?'Declared inputs are compatible. Frozen numerical replay and observation screening run with the study.':state.compatibility?`${issues.length} compatibility issue${issues.length===1?'':'s'} to resolve.`:'';
  $('field-issues').innerHTML=issues.length?`<ul class="field-issues">${issues.map(i=>`<li>${esc(i.message)}</li>`).join('')}</ul>`:'';
  $('field-file-state').textContent=state.descriptorRaw?`${fileLabel} · ${state.busy==='check'?'Checking compatibility':state.compatibility?.ready?'Declared compatible':state.compatibility?'Needs review':'Compatibility not checked'}`:'Use the template to declare instrument calibration, reference plane, averaging, actual configuration and observed-cell mappings.';
  const facts=state.inputs?[['Capture',state.inputs.capture.id],['Prediction',state.inputs.prediction.id],['Capture SHA-256',state.inputs.capture.sha256],['Prediction SHA-256',state.inputs.prediction.sha256],['Source verification','Declared only; not independently verified']]:[];
  $('field-source-facts').innerHTML=facts.length?table(['Frozen identity','Value'],facts):'';
 }
 function sites(){
  const all=state.inputs?.sites||[],visible=all.filter(s=>`${s.id} ${s.label}`.toLowerCase().includes(siteFilter.toLowerCase())).slice(0,siteLimit);
  const signature=JSON.stringify(visible);
  if(signature!==siteSignature){siteSignature=signature;$('field-sites').innerHTML=visible.map(s=>`<label><input type="checkbox" value="${esc(s.id)}" ${state.options.heldoutSites.includes(s.id)?'checked':''}> <span>${esc(s.label)}<small>${esc(s.id)}</small></span></label>`).join('')||'<p class="helper">No matching frozen sites.</p>';}
  for(const input of $('field-sites').querySelectorAll('input'))input.checked=state.options.heldoutSites.includes(input.value);
  $('field-site-count').textContent=`${state.options.heldoutSites.length} of ${all.length} sites reserved · ${visible.length} matching sites shown.`;show('field-more-sites',all.filter(s=>`${s.id} ${s.label}`.toLowerCase().includes(siteFilter.toLowerCase())).length>visible.length);
 }
 function result(){
  const study=state.study,r=study?.result;show('field-output',Boolean(r));show('field-stale',state.studyStale);
  if(!r)return;const signature=JSON.stringify([study.id,r]);if(signature===resultSignature)return;resultSignature=signature;
  $('field-result-source').textContent=`${study.id} · capture ${study.spec.capture_id} · prediction ${study.spec.prediction_id}`;$('field-result-status').textContent=statusLabels[r.status]||r.status;
  const c=r.calibration,q=r.quality;$('field-cards').innerHTML=[['Compatible readings',pct(q.compatiblePct),`${q.eligible.toLocaleString()} of ${q.total.toLocaleString()} observations`],['Candidate offset',Number.isFinite(c.offsetDb)?signed(c.offsetDb)+' dB':'Withheld',`${c.training.bins} training bins · ${c.training.sites} sites`],['Supported holdout',String(c.holdout.bins),`${c.holdout.sites} sites · ${c.unscoredHoldoutBins} unsupported bins`]].map(([label,value,detail])=>`<article><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(detail)}</small></article>`).join('');
  $('field-metrics').innerHTML=table(['Holdout error (dB)','Raw model','Offset candidate'],[['Bias',number(c.holdout.raw?.biasDb),number(c.holdout.adjusted?.biasDb)],['MAE',number(c.holdout.raw?.maeDb),number(c.holdout.adjusted?.maeDb)],['RMSE',number(c.holdout.raw?.rmseDb),number(c.holdout.adjusted?.rmseDb)]]);
  $('field-reasons').innerHTML=table(['Screening / evidence','Count'],[['Excluded readings',q.excluded],...Object.entries(q.reasons),['Quarantined eligible readings',c.quarantined],...Object.entries(c.quarantineReasons),['Raw holdout bins (all)',c.holdout.totalBins],['Unsupported holdout bins',c.unscoredHoldoutBins],['Frozen replay observations',r.replay.rows],['Maximum replay error',r.replay.maxAbsoluteError]]);$('field-limits').textContent=r.limitations;
 }
 function records(){
  const p=state.page,signature=JSON.stringify([p,state.pageLoading]);if(signature===pageSignature)return;pageSignature=signature;
  $('field-page').textContent=state.pageLoading?'Loading saved rows…':p?.total?`${p.offset+1}–${Math.min(p.total,p.offset+p.rows.length)} of ${p.total.toLocaleString()}`:'No saved rows loaded';$('field-page-prev').disabled=state.pageLoading||!p||!p.offset;$('field-page-next').disabled=state.pageLoading||!p||p.offset+p.rows.length>=p.total;
  if(!p){$('field-records').innerHTML='';return;}
  let headers,rows;
  if(p.kind==='observations'){headers=['Observation / UTC','Observed cell / site','Screening','Measured (dBm)','Model (dBm)'];rows=p.rows.map(r=>[`${r.index+1} / ${utc(r.t)}`,`${r.captureCellId||'—'} / ${r.siteId||'—'}`,r.reason||'Eligible',number(r.measuredDbm),number(r.predictedDbm)]);}
  else if(p.kind==='bins'){headers=['Split / site','Carrier / mode','Route (m)','Readings','Residual (dB)','Adjusted (dB)'];rows=p.rows.map(r=>[`${r.partition} / ${r.siteId}`,`${r.rat} ${r.band} / ${r.environment}`,number(r.chainageM),r.samples,number(r.residualDb),number(r.adjustedResidualDb)]);}
  else{headers=['Group','Bins / sites','Raw RMSE (dB)','Paired raw RMSE (dB)','Adjusted RMSE (dB)','Unscored bins'];rows=p.rows.map(r=>[[r.partition,r.siteId,r.rat,r.band,r.frequencyMHz&&`${r.frequencyMHz} MHz`,r.bandwidthMHz&&`${r.bandwidthMHz} MHz BW`,r.environment].filter(Boolean).join(' / '),`${r.bins} / ${r.sites}`,number(r.raw?.rmseDb),number(r.pairedRaw?.rmseDb),number(r.adjusted?.rmseDb),r.unscoredBins]);}
  $('field-records').innerHTML=table(headers,rows);for(const el of $('field-records').querySelectorAll('.table-wrap')){el.tabIndex=0;el.setAttribute('role','region');el.setAttribute('aria-label','Scrollable saved field-study records');}
 }
 function render(){
  if(!active)return;if(!state.study)autoPageStudy='';sources();sites();result();records();$('field-error').textContent=state.error;show('field-error',Boolean(state.error));$('field-rows-reload').disabled=state.pageLoading||state.study?.status!=='completed';
  const workspace=getWorkspace(),scope=workspace.test?.scope||{};$('field-scope').textContent=[scope.region||scope.region_id,scope.project||scope.project_id,scope.task||scope.task_id].filter(Boolean).join(' / ');
  for(const [id,value]of [['field-cutoff',cutoff(state.options.cutoffT)],['field-time-gap',state.options.timeGapMs/1000],['field-direction',state.options.direction],['field-tolerance',state.options.toleranceM],['field-route-gap',state.options.gapMs/1000],['field-minimum',state.options.minimumCompatiblePct]])setValue(id,value);
  $('field-options-state').textContent=state.optionError;$('field-run').disabled=!state.canRun;$('field-check').disabled=!state.inputs||!state.descriptorRaw||Boolean(state.busy);$('field-template').disabled=!state.inputs||Boolean(state.busy);$('field-file').disabled=!state.inputs||Boolean(state.busy&&state.busy!=='check');for(const id of ['field-capture','field-prediction'])$(id).disabled=Boolean(state.busy);$('field-cancel').disabled=Boolean(state.busy);show('field-cancel',state.running);show('field-progress-bar',state.running);$('field-progress-bar').value=state.study?.progress||0;
  $('field-progress').textContent=state.busy==='submit'?'Saving frozen study inputs…':state.study?`${state.study.id} · ${state.study.status}${state.running?` · ${state.study.progress}%`:''}${state.study.error?' · '+state.study.error:''}`:'';
  const signature=JSON.stringify(state.history);if(signature!==historySignature){historySignature=signature;$('field-history').innerHTML=state.history.map(s=>`<button data-study="${esc(s.id)}" type="button">${esc(s.id)} · ${esc(s.status)}<small>${esc(s.spec.capture_id)} → ${esc(s.spec.prediction_id)}</small></button>`).join('')||'<p class="helper">No saved studies for this Task.</p>';}
  for(const el of $('field-validation').querySelectorAll('.table-wrap')){el.tabIndex=0;el.setAttribute('role','region');if(!el.hasAttribute('aria-label'))el.setAttribute('aria-label','Scrollable field-study evidence');}
  if(state.study?.status==='completed'&&!state.page&&!state.pageLoading&&autoPageStudy!==state.study.id){autoPageStudy=state.study.id;void state.loadPage($('field-record-kind').value,0);}
 }
 state.listen(render);
 for(const id of ['field-capture','field-prediction'])$(id).onchange=()=>{reading++;$('field-file').value='';$('field-file-state').textContent='Upload a descriptor for the selected inputs.';void state.selectSources($('field-capture').value,$('field-prediction').value);};
 $('field-template').onclick=()=>download('ndt-field-measurement-template.json',JSON.stringify(state.inputs.descriptorTemplate,null,2)+'\n','application/json');
 $('field-file').onchange=async event=>{const file=event.target.files[0],version=++reading,identity=[state.captureId,state.predictionId].join('/');state.setDescriptor('');if(!file)return;
  if(!file.size||file.size>128*1024){state.error='Select a measurement JSON file between 1 byte and 128 KiB.';state.emit();return;}
  try{const raw=await file.text();if(version!==reading||identity!==[state.captureId,state.predictionId].join('/'))return;fileLabel=`${file.name} · ${(file.size/1024).toFixed(1)} KiB`;state.setDescriptor(raw);}
  catch(e){state.error=e.message;state.emit();}};
 $('field-check').onclick=()=>state.check();$('field-run').onclick=()=>state.submit();$('field-cancel').onclick=()=>state.cancel();
 for(const [id,key,factor]of [['field-time-gap','timeGapMs',1000],['field-tolerance','toleranceM',1],['field-route-gap','gapMs',1000],['field-minimum','minimumCompatiblePct',1]])$(id).oninput=event=>state.setOptions({[key]:event.target.valueAsNumber*factor});
 $('field-cutoff').oninput=event=>state.setOptions({cutoffT:/^\d{4}-\d\d-\d\dT.*(?:Z|[+-]\d\d:\d\d)$/.test(event.target.value)?Date.parse(event.target.value):NaN});$('field-direction').onchange=event=>state.setOptions({direction:event.target.value});
 $('field-sites').onchange=event=>{if(event.target.type!=='checkbox')return;const sites=new Set(state.options.heldoutSites);event.target.checked?sites.add(event.target.value):sites.delete(event.target.value);state.setOptions({heldoutSites:[...sites].sort()});};$('field-site-search').oninput=event=>{siteFilter=event.target.value;siteLimit=50;sites();};$('field-more-sites').onclick=()=>{siteLimit+=50;sites();};
 $('field-record-kind').onchange=()=>state.loadPage($('field-record-kind').value,0);$('field-page-prev').onclick=()=>state.loadPage(state.page.kind,Math.max(0,state.page.offset-state.page.limit));$('field-page-next').onclick=()=>state.loadPage(state.page.kind,state.page.offset+state.page.limit);
 $('field-rows-reload').onclick=()=>{const kind=$('field-record-kind').value;void state.loadPage(kind,state.page?.kind===kind?state.page.offset:0);};
 $('field-history-refresh').onclick=()=>state.refreshHistory();$('field-history').onclick=event=>{const id=event.target.closest('[data-study]')?.dataset.study;if(id)void state.openStudy(id);};
 $('field-export').onclick=async()=>{const id=state.study?.id;if(!id)return;$('field-export').disabled=true;try{const data=await api.exportFieldStudy(id);download(`${id}-field-study.json`,JSON.stringify(data,null,2)+'\n','application/json');}catch(e){state.error=e.message;state.emit();}finally{$('field-export').disabled=false;}};
 return {state,sync(){const w=getWorkspace(),before=state.scope;state.setContext(w.tests,w.test?.scope||w.scope);if(before!==state.scope){reading++;$('field-file').value='';fileLabel='';}},active(value){active=value;clearInterval(timer);if(value){render();void state.refreshHistory();timer=setInterval(()=>state.poll(),1500);}},dispose(){clearInterval(timer);reading++;state.dispose();}};
}
